L={}
inputs={'t':t,'x':x,'v':v}
funcs={'1':lambda z:np.ones_like(z),'':lambda z:z,'2':lambda z:z**2,'3':lambda z:z**3,'sqrt':np.sqrt,'log':np.log,'exp-':lambda z:np.exp(-z),'sin':np.sin,'cos':np.cos,'inv':lambda z:1/z,'tanh':np.tanh}
