keys=list(L)
for i,k1 in enumerate(['x','v','t']): pass
pairs={}
for k1 in keys:
    for k2 in ['x','v','t']:
        pairs[f'{k1}*{k2}']=L[k1]*inputs[k2]
L.update(pairs)
keys=list(L)
