xs=[np.ones_like(x),x,x**2,x**3]
res=[]
for gn,g in gs.items():
    if g is None:
        Bs=[*xs,t,np.sqrt(t),*[ (t*xx) for xx in xs[1:]], *[np.sqrt(t)*xx for xx in xs[1:]]]
    else:
        Bs=[*xs,*[g*xx for xx in xs]]
    A=np.column_stack(Bs); c,_,_,_=np.linalg.lstsq(A,a,rcond=None)
    res.append((round(np.mean((a-A@c)**2)/np.var(a),6),gn))
print(sorted(res))
# two-g combo
for g1,g2 in [('t','sqrt'),('t','log'),('t','1/t'),('t','exp-t'),('t','cos t')]:
    G={'t':t,'sqrt':np.sqrt(t),'log':np.log(t),'1/t':1/t,'exp-t':np.exp(-t),'cos t':np.cos(t)}
    Bs=xs+[G[g1]*xx for xx in xs]+[G[g2]*xx for xx in xs]
